import os, urllib.request
from pathlib import Path
import numpy as np
import cv2
import mediapipe as mp
from mediapipe.tasks import python as mp_python
from mediapipe.tasks.python import vision as mp_vision

MODEL_DIR     = Path("models")
MP_VARIANT    = "full"
MP_MODEL_PATH = MODEL_DIR / f"pose_landmarker_{MP_VARIANT}.task"
ARCHIVE_ROOT  = Path("archive")

POSE_LANDMARK_NAMES = [
    "NOSE","LEFT_EYE_INNER","LEFT_EYE","LEFT_EYE_OUTER","RIGHT_EYE_INNER","RIGHT_EYE",
    "RIGHT_EYE_OUTER","LEFT_EAR","RIGHT_EAR","LEFT_MOUTH","RIGHT_MOUTH","LEFT_SHOULDER",
    "RIGHT_SHOULDER","LEFT_ELBOW","RIGHT_ELBOW","LEFT_WRIST","RIGHT_WRIST","LEFT_PINKY",
    "RIGHT_PINKY","LEFT_INDEX","RIGHT_INDEX","LEFT_THUMB","RIGHT_THUMB","LEFT_HIP","RIGHT_HIP",
    "LEFT_KNEE","RIGHT_KNEE","LEFT_ANKLE","RIGHT_ANKLE","LEFT_HEEL","RIGHT_HEEL",
    "LEFT_FOOT_INDEX","RIGHT_FOOT_INDEX"]
KPTS = len(POSE_LANDMARK_NAMES)
IDX  = {n: i for i, n in enumerate(POSE_LANDMARK_NAMES)}
L_HIP, R_HIP           = IDX["LEFT_HIP"], IDX["RIGHT_HIP"]
L_SHOULDER, R_SHOULDER = IDX["LEFT_SHOULDER"], IDX["RIGHT_SHOULDER"]

POSE_CONNECTIONS = [
    (0,1),(1,2),(2,3),(3,7),(0,4),(4,5),(5,6),(6,8),(9,10),
    (11,12),(11,13),(13,15),(15,17),(15,19),(15,21),(17,19),
    (12,14),(14,16),(16,18),(16,20),(16,22),(18,20),
    (11,23),(12,24),(23,24),(23,25),(25,27),(27,29),(27,31),(29,31),
    (24,26),(26,28),(28,30),(28,32),(30,32)]

LR_PAIRS = [(IDX[a], IDX[b]) for a, b in [
    ("LEFT_EYE_INNER","RIGHT_EYE_INNER"),("LEFT_EYE","RIGHT_EYE"),
    ("LEFT_EYE_OUTER","RIGHT_EYE_OUTER"),("LEFT_EAR","RIGHT_EAR"),
    ("LEFT_MOUTH","RIGHT_MOUTH"),("LEFT_SHOULDER","RIGHT_SHOULDER"),
    ("LEFT_ELBOW","RIGHT_ELBOW"),("LEFT_WRIST","RIGHT_WRIST"),
    ("LEFT_PINKY","RIGHT_PINKY"),("LEFT_INDEX","RIGHT_INDEX"),
    ("LEFT_THUMB","RIGHT_THUMB"),("LEFT_HIP","RIGHT_HIP"),
    ("LEFT_KNEE","RIGHT_KNEE"),("LEFT_ANKLE","RIGHT_ANKLE"),
    ("LEFT_HEEL","RIGHT_HEEL"),("LEFT_FOOT_INDEX","RIGHT_FOOT_INDEX")]]

def normalize_frame(frame, vis_th=0.5):
    out = frame.copy()
    hips_ok = (out[L_HIP, 3] >= vis_th) and (out[R_HIP, 3] >= vis_th)
    center = ((out[L_HIP, :2] + out[R_HIP, :2]) / 2.0 if hips_ok
              else (out[out[:, 3] >= vis_th, :2].mean(axis=0)
                    if (out[:, 3] >= vis_th).any() else np.zeros(2, np.float32)))
    out[:, :2] -= center
    sh_ok = (out[L_SHOULDER, 3] >= vis_th) and (out[R_SHOULDER, 3] >= vis_th)
    if sh_ok:
        scale = np.linalg.norm(out[L_SHOULDER, :2] - out[R_SHOULDER, :2]) + 1e-6
    else:
        m = out[:, 3] >= vis_th
        scale = (np.linalg.norm(out[m, :2], axis=1).mean() + 1e-6) if m.sum() >= 2 else 0.2
    out[:, :2] /= scale
    out[:, :2] = np.clip(out[:, :2], -3.0, 3.0)
    return out


def normalize_frame_3d(frame, vis_th=0.5):
    # Normalise x, y, z: same centre/scale as normalize_frame(), extended to z.
    out = frame.copy()
    hips_ok = (out[L_HIP, 3] >= vis_th) and (out[R_HIP, 3] >= vis_th)
    if hips_ok:
        cxy = (out[L_HIP, :2] + out[R_HIP, :2]) / 2.0
        cz  = (out[L_HIP, 2]  + out[R_HIP, 2])  / 2.0
    elif (out[:, 3] >= vis_th).any():
        m = out[:, 3] >= vis_th
        cxy = out[m, :2].mean(axis=0)
        cz  = float(out[m, 2].mean())
    else:
        cxy, cz = np.zeros(2, np.float32), 0.0
    out[:, :2] -= cxy
    out[:, 2]  -= cz
    sh_ok = (out[L_SHOULDER, 3] >= vis_th) and (out[R_SHOULDER, 3] >= vis_th)
    if sh_ok:
        scale = np.linalg.norm(out[L_SHOULDER, :2] - out[R_SHOULDER, :2]) + 1e-6
    else:
        m = out[:, 3] >= vis_th
        scale = (np.linalg.norm(out[m, :2], axis=1).mean() + 1e-6) if m.sum() >= 2 else 0.2
    out[:, :3] /= scale
    out[:, :3] = np.clip(out[:, :3], -3.0, 3.0)
    return out


def download_mp_model():
    MODEL_DIR.mkdir(exist_ok=True)
    if MP_MODEL_PATH.exists():
        return
    url = ("https://storage.googleapis.com/mediapipe-models/pose_landmarker/"
           f"pose_landmarker_{MP_VARIANT}/float16/latest/pose_landmarker_{MP_VARIANT}.task")
    urllib.request.urlretrieve(url, MP_MODEL_PATH)


def make_landmarker():
    base = mp_python.BaseOptions(model_asset_path=str(MP_MODEL_PATH))
    opts = mp_vision.PoseLandmarkerOptions(
        base_options=base, num_poses=1, min_pose_detection_confidence=0.5,
        min_pose_presence_confidence=0.5, min_tracking_confidence=0.5)
    return mp_vision.PoseLandmarker.create_from_options(opts)


class PoseDetector:
    def __init__(self, landmarker, vis_th=0.5):
        self.lm = landmarker; self.vis_th = vis_th
    def _infer(self, frame_bgr):
        rgb = cv2.cvtColor(frame_bgr, cv2.COLOR_BGR2RGB)
        res = self.lm.detect(mp.Image(image_format=mp.ImageFormat.SRGB, data=rgb))
        if not res.pose_landmarks:
            return None
        return np.array([[p.x, p.y, p.z, p.visibility]
                         for p in res.pose_landmarks[0]], np.float32)
    def detect_array(self, frame_bgr):
        return self._infer(frame_bgr)
    def detect(self, frame_bgr):
        arr = self._infer(frame_bgr)
        if arr is None:
            return None
        return [{"index": i, "name": POSE_LANDMARK_NAMES[i],
                 "x": float(arr[i,0]), "y": float(arr[i,1]),
                 "z": float(arr[i,2]), "visibility": float(arr[i,3])} for i in range(KPTS)]


def draw_pose(frame_bgr, arr, draw_box=True):
    img = frame_bgr.copy()
    if arr is None:
        return img
    h, w = img.shape[:2]
    pts = [(int(x*w), int(y*h)) for x, y, _, _ in arr]
    for a, b in POSE_CONNECTIONS:
        if a < len(pts) and b < len(pts):
            cv2.line(img, pts[a], pts[b], (0,200,0), 2)
    for (x, y), v in zip(pts, arr[:, 3]):
        if v >= 0.3:
            cv2.circle(img, (x, y), 3, (0,0,255), -1)
    if draw_box:
        vis = arr[:, 3] >= 0.3
        if vis.any():
            xs, ys = arr[vis,0]*w, arr[vis,1]*h
            x0, y0 = int(xs.min())-15, int(ys.min())-15
            x1, y1 = int(xs.max())+15, int(ys.max())+15
            cv2.rectangle(img, (max(0,x0),max(0,y0)), (min(w,x1),min(h,y1)), (255,150,0), 2)
            cv2.putText(img, "person", (max(0,x0),max(0,y0-6)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255,150,0), 2)
    return img


def keypoint_stream(video_path, detector, stride=2, max_frames=None):
    cap = cv2.VideoCapture(str(video_path))
    fidx = 0
    while True:
        ok, frame = cap.read()
        if not ok or (max_frames is not None and fidx >= max_frames):
            break
        if fidx % stride == 0:
            yield frame, detector.detect_array(frame)
        fidx += 1
    cap.release()


def video_full_path(clip_path):
    return ARCHIVE_ROOT / clip_path.lstrip("/\\")


def init_detector():
    download_mp_model()
    return PoseDetector(make_landmarker())
